package com.desktodo.app;
import android.app.*;import android.widget.*;import android.text.*;import org.json.*;import java.util.*;
/** Local retained history; searching never restores or changes completion counts. */
final class HistoryPanel {
 static final String[] KEYS={"all","completed","skipped","deleted"},LABELS={"全部","已完成","已跳过","已删除"};
 final MainActivity a;String query="",kind="all";LinearLayout results;TextView count;int limit=20;
 HistoryPanel(MainActivity a){this.a=a;}
 static List<JSONObject> records(JSONArray history,String query,String kind){String needle=query.trim().toLowerCase(Locale.ROOT);Set<String> seen=new HashSet<>();List<JSONObject> values=new ArrayList<>();for(int i=history.length()-1;i>=0;i--){JSONObject t=history.optJSONObject(i);if(t==null||t.optString("id").isEmpty()||!seen.add(t.optString("id")))continue;if(!kind.equals("all")&&!t.optString("recordType").equals(kind))continue;if(!needle.isEmpty()&&!t.optString("title").toLowerCase(Locale.ROOT).contains(needle))continue;values.add(t);}return values;}
 static int index(JSONArray history,JSONObject record){for(int i=history.length()-1;i>=0;i--){JSONObject t=history.optJSONObject(i);if(t!=null&&t.optString("id").equals(record.optString("id")))return ScreenSync.same(t,record)?i:-1;}return -1;}
 void render(){LinearLayout intro=a.card("找回以前的事项");intro.addView(a.text("仅搜索本机保留记录。完成、跳过和删除分别查看；恢复前会再次确认。",14,a.muted));EditText input=new EditText(a);input.setHint("搜索事项文字");input.setSingleLine(true);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});input.setText(query);input.setMinimumHeight(a.dp(52));intro.addView(input);Spinner filter=new Spinner(a);filter.setMinimumHeight(a.dp(48));filter.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,LABELS));for(int i=0;i<KEYS.length;i++)if(KEYS[i].equals(kind))filter.setSelection(i);intro.addView(filter);count=a.text("",13,a.muted);intro.addView(count);a.button(intro,"清空搜索",()->input.setText(""));results=new LinearLayout(a);results.setOrientation(1);a.body.addView(results);input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int c){query=s.toString();limit=20;update();}public void afterTextChanged(Editable e){}});filter.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,android.view.View v,int pos,long id){kind=KEYS[pos];limit=20;update();}public void onNothingSelected(AdapterView<?> p){}});a.body.addView(a.text("本机历史最多保留100条；不包含已经裁剪或尚未同步到本机的记录。恢复沿用原截止时间，可能仍逾期；满八项或重复下一次已修改时拒绝恢复。",13,a.muted));update();}
 void update(){if(results==null||count==null)return;results.removeAllViews();List<JSONObject> values=records(a.history,query,kind);count.setText("找到 "+values.size()+" 项 · 仅本机保留记录");if(values.isEmpty())results.addView(a.text("没有匹配记录，可清空关键词或切换类型。",15,a.muted));for(JSONObject record:values.subList(0,Math.min(limit,values.size()))){LinearLayout row=new LinearLayout(a);row.setOrientation(1);row.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));TextView title=a.text(record.optString("title"),17,a.ink);title.setTextIsSelectable(true);row.addView(title);String type=record.optString("recordType");String label=type.equals("completed")?"已完成":type.equals("skipped")?"已跳过":type.equals("deleted")?"已删除":"历史记录";String time=type.equals("deleted")?record.optString("deletedAt"):record.optString("completedAt");try{time=DeskModel.updatedTime(java.time.Instant.parse(time).toEpochMilli());}catch(Exception e){time="时间未记录";}row.addView(a.text(label+" · "+time,13,a.muted));a.button(row,"恢复到清单",()->restore(record));results.addView(row);}if(values.size()>limit)a.button(results,"显示更多记录",()->{limit+=20;update();});}
 void restore(JSONObject source){JSONObject record=DeskModel.copy(source);new AlertDialog.Builder(a).setTitle("恢复这条事项？").setMessage(record.optString("title")+"\n\n保留原截止时间，可能仍逾期。重复事项会核对下一次是否被修改；不会切换布局或全刷。").setNegativeButton("取消",null).setPositiveButton("恢复",(d,w)->{int at=index(a.history,record);if(at<0){a.toast("记录已改变，请重新选择。");update();return;}a.restore(at);}).show();}
}
